// Jonker-Volgenant dense LAP, minimization. Adapted from the public-domain
// implementation by Roy Jonker (magic-software / common LAPJV ports).
#include <cstdint>
#include <cstring>
#include <vector>
#include <cmath>
#include <limits>
#include <iostream>
#include <chrono>
#include <random>

static constexpr double BIG = 1.0e18;

// cost is row-major n*n
void lapjv(int n, const double* cost, int* rowsol, int* colsol) {
    std::vector<double> u(n), v(n), d(n);
    std::vector<int> pred(n), free_rows;
    std::vector<char> unique(n, 1);
    free_rows.reserve(n);

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double h = cost[i * n + j];
            if (h < minv) { minv = h; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            unique[imin] = 0;
            colsol[j] = -1;
        }
    }

    // REDUCTION TRANSFER
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) {
            free_rows.push_back(i);
            continue;
        }
        if (unique[i]) {
            int j = rowsol[i];
            double minv = BIG;
            for (int jj = 0; jj < n; ++jj) {
                if (jj == j) continue;
                double h = cost[i * n + jj] - v[jj];
                if (h < minv) minv = h;
            }
            v[j] -= minv;
        } else {
            free_rows.push_back(i);
            rowsol[i] = -1;
            // colsol of its column already not uniquely owned? The first assignment
            // may still point here. Clear it.
        }
    }
    // clear colsol entries whose row was freed
    for (int j = 0; j < n; ++j) {
        int i = colsol[j];
        if (i >= 0 && rowsol[i] != j) colsol[j] = -1;
    }

    // AUGMENTING ROW REDUCTION
    int freecnt = (int)free_rows.size();
    for (int pass = 0; pass < 2 && freecnt > 0; ++pass) {
        int k = 0;
        int new_free = 0;
        while (k < freecnt) {
            int i = free_rows[k++];
            double umin = cost[i * n] - v[0];
            double usub = BIG;
            int j1 = 0, j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = cost[i * n + j] - v[j];
                if (h < umin) {
                    usub = umin; j2 = j1;
                    umin = h; j1 = j;
                } else if (h < usub) {
                    usub = h; j2 = j;
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            if (i0 >= 0) {
                if (umin < usub) {
                    free_rows[new_free++] = i0;
                    rowsol[i0] = -1;
                } else {
                    free_rows[new_free++] = i;
                    continue;
                }
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
        freecnt = new_free;
    }

    // AUGMENTATION
    std::vector<char> scanned(n);
    for (int kf = 0; kf < freecnt; ++kf) {
        int f = free_rows[kf];
        int endofpath = -1;
        for (int j = 0; j < n; ++j) {
            d[j] = cost[f * n + j] - v[j];
            pred[j] = f;
            scanned[j] = 0;
        }
        int last = 0;
        std::vector<int> readycols;
        // scan columns in order of increasing d using selection (n is moderate)
        while (true) {
            // find unscanned column with minimum d
            double mind = BIG;
            int jmin = -1;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            }
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i < 0) { endofpath = jmin; 
                // dual update: columns scanned get v += d - mind
                for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += d[j] - mind;
                break;
            }
            // relax
            double base = cost[i * n + jmin] - v[jmin];
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double cand = mind + cost[i * n + j] - v[j] - base;
                if (cand < d[j]) { d[j] = cand; pred[j] = i; }
            }
        }
        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == f) break;
            j = jnext;
        }
    }
}

int main() {
    int n = 600;
    std::mt19937 rng(1);
    std::uniform_real_distribution<double> dist(0.0, 1.0);
    std::vector<double> cost(n * n);
    for (auto& x : cost) x = dist(rng);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    auto t0 = std::chrono::steady_clock::now();
    lapjv(n, cost.data(), rowsol.data(), colsol.data());
    auto t1 = std::chrono::steady_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    // feasibility
    std::vector<char> seen(n, 0);
    int bad = 0;
    double csum = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0 || j >= n || seen[j]) bad++;
        else seen[j] = 1;
        csum += cost[i * n + j];
    }
    std::cout << "ms " << ms << " bad " << bad << " cost " << csum << "\n";
}
