// Dense LAPJV (Jonker-Volgenant), minimization.
// Structure follows the well-known public-domain implementation
// (Jonker & Volgenant 1987; common ports such as gatagat/lap).
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <random>
#include <vector>

static void lapjv(int n, const double* cost, int* rowsol, int* colsol) {
    const double INF = 1e18;
    std::vector<double> u(n, 0.0), v(n, 0.0), dist(n);
    std::vector<int> pred(n), free_rows;
    std::vector<char> cols_seen(n);

    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    // ---- column reduction ----
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double h = cost[(size_t)i * n + j];
            if (h < minv) {
                minv = h;
                imin = i;
            }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;  // conflict, leave free
        }
    }

    // ---- reduction transfer on uniquely matched rows ----
    free_rows.clear();
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j == -1) {
            free_rows.push_back(i);
            continue;
        }
        // is this match unique? colsol[j] == i means we kept it
        if (colsol[j] != i) {
            rowsol[i] = -1;
            free_rows.push_back(i);
            continue;
        }
        double minv = INF;
        const double* row = cost + (size_t)i * n;
        for (int jj = 0; jj < n; ++jj) {
            if (jj == j) continue;
            double h = row[jj] - v[jj];
            if (h < minv) minv = h;
        }
        v[j] = row[j] - minv;
    }

    // ---- augmenting row reduction, two passes ----
    for (int pass = 0; pass < 2; ++pass) {
        int nf = (int)free_rows.size();
        int w = 0;
        for (int kf = 0; kf < nf; ++kf) {
            int i = free_rows[kf];
            const double* row = cost + (size_t)i * n;
            int j1 = 0;
            double h1 = row[0] - v[0];
            double h2 = INF;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < h1) {
                    h2 = h1;
                    j2 = j1;
                    h1 = h;
                    j1 = j;
                } else if (h < h2) {
                    h2 = h;
                    j2 = j;
                }
            }
            int i0 = colsol[j1];
            double gap = h2 - h1;
            if (gap > 0.0) {
                v[j1] -= gap;
            } else if (i0 >= 0 && j2 >= 0) {
                // not unique: take second minimum column
                j1 = j2;
                i0 = colsol[j1];
            }
            if (i0 >= 0) {
                if (gap > 0.0) {
                    // steal and free previous row
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    rowsol[i0] = -1;
                    free_rows[w++] = i0;
                } else {
                    // cannot improve; keep free
                    free_rows[w++] = i;
                }
            } else {
                rowsol[i] = j1;
                colsol[j1] = i;
            }
        }
        free_rows.resize(w);
    }

    // ---- augment remaining free rows (Dijkstra on residual) ----
    std::vector<int> still_free;
    for (int i = 0; i < n; ++i)
        if (rowsol[i] == -1) still_free.push_back(i);
    // also any listed
    if (still_free.empty()) still_free = free_rows;

    for (int f : still_free) {
        if (rowsol[f] != -1) continue;
        const double* frow = cost + (size_t)f * n;
        for (int j = 0; j < n; ++j) {
            dist[j] = frow[j] - v[j];
            pred[j] = f;
            cols_seen[j] = 0;
        }
        int jmin = 0;
        double mind = dist[0];
        for (int j = 1; j < n; ++j) {
            if (dist[j] < mind) {
                mind = dist[j];
                jmin = j;
            }
        }
        int endc = -1;
        while (true) {
            cols_seen[jmin] = 1;
            int i = colsol[jmin];
            if (i == -1) {
                endc = jmin;
                break;
            }
            const double* irow = cost + (size_t)i * n;
            double base = irow[jmin] - v[jmin];
            int next = -1;
            double next_d = INF;
            for (int j = 0; j < n; ++j) {
                if (cols_seen[j]) continue;
                double cand = mind + irow[j] - v[j] - base;
                if (cand < dist[j]) {
                    dist[j] = cand;
                    pred[j] = i;
                }
                if (dist[j] < next_d) {
                    next_d = dist[j];
                    next = j;
                }
            }
            mind = next_d;
            jmin = next;
        }
        // dual update
        for (int j = 0; j < n; ++j) {
            if (cols_seen[j]) v[j] += dist[j] - mind;
        }
        // augment
        int j = endc;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == f) break;
            j = nxt;
        }
    }
}

int main() {
    int n = 400;
    std::mt19937 rng(1);
    std::uniform_real_distribution<double> dist(0.0, 1.0);
    std::vector<double> cost((size_t)n * n);
    for (auto& x : cost) x = dist(rng);
    std::vector<int> rowsol(n), colsol(n);
    auto t0 = std::chrono::steady_clock::now();
    lapjv(n, cost.data(), rowsol.data(), colsol.data());
    auto t1 = std::chrono::steady_clock::now();
    std::vector<char> seen(n, 0);
    int bad = 0;
    double csum = 0;
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0 || j >= n || seen[j]) bad++;
        else seen[j] = 1;
        if (j >= 0 && j < n) csum += cost[(size_t)i * n + j];
    }
    std::cout << "ms " << std::chrono::duration<double, std::milli>(t1 - t0).count()
              << " bad " << bad << " cost " << csum << "\n";
    return 0;
}
