static PyObject* py_lapjv(PyObject*, PyObject* args) {
    Py_buffer buf;
    if (!PyArg_ParseTuple(args, "y*", &buf)) return NULL;
    if (buf.ndim != 2 || buf.shape[0] != buf.shape[1] || buf.itemsize != (Py_ssize_t)sizeof(double)) {
        PyBuffer_Release(&buf);
        PyErr_SetString(PyExc_ValueError, "need square float64 C-contiguous matrix");
        return NULL;
    }
    // require C contiguous
    if (buf.strides[1] != (Py_ssize_t)sizeof(double) || buf.strides[0] != buf.shape[1] * (Py_ssize_t)sizeof(double)) {
        PyBuffer_Release(&buf);
        PyErr_SetString(PyExc_ValueError, "need C-contiguous");
        return NULL;
    }
    int n = (int)buf.shape[0];
    std::vector<int> rowsol(n), colsol(n);
    lapjv(n, static_cast<const double*>(buf.buf), rowsol.data(), colsol.data());
    PyBuffer_Release(&buf);
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(rowsol[i]));
    return list;
}

static PyMethodDef methods[] = {
    {"lapjv", py_lapjv, METH_VARARGS, "row->col assignment"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "lapjv_ext", NULL, -1, methods};
PyMODINIT_FUNC PyInit_lapjv_ext(void) { return PyModule_Create(&mod); }
