#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <vector>

// Faithful dense LAPJV (Jonker-Volgenant), minimization.
// Row solution x[i] = column matched to row i.

static constexpr double LARGE = 1.0e18;

static int ccrrt_dense(int n, const double* cost, int* free_rows, int* x, int* y, double* v) {
    std::fill(x, x + n, -1);
    std::fill(v, v + n, LARGE);
    std::fill(y, y + n, 0);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            double c = row[j];
            if (c < v[j]) {
                v[j] = c;
                y[j] = i;
            }
        }
    }
    std::vector<char> unique(n, 1);
    for (int j = n - 1; j >= 0; --j) {
        int i = y[j];
        if (x[i] < 0) {
            x[i] = j;
        } else {
            unique[i] = 0;
            y[j] = -1;
        }
    }
    int n_free = 0;
    for (int i = 0; i < n; ++i) {
        if (x[i] < 0) {
            free_rows[n_free++] = i;
        } else if (unique[i]) {
            int j = x[i];
            double minv = LARGE;
            const double* row = cost + (size_t)i * n;
            for (int j2 = 0; j2 < n; ++j2) {
                if (j2 == j) continue;
                double c = row[j2] - v[j2];
                if (c < minv) minv = c;
            }
            v[j] -= minv;
        }
    }
    return n_free;
}

static int carr_dense(int n, const double* cost, int n_free_rows, int* free_rows,
                      int* x, int* y, double* v) {
    int current = 0;
    int new_free_rows = 0;
    int rr_cnt = 0;
    while (current < n_free_rows) {
        rr_cnt++;
        int free_i = free_rows[current++];
        const double* row = cost + (size_t)free_i * n;
        int j1 = 0;
        double v1 = row[0] - v[0];
        int j2 = -1;
        double v2 = LARGE;
        for (int j = 1; j < n; ++j) {
            double c = row[j] - v[j];
            if (c < v2) {
                if (c >= v1) {
                    v2 = c;
                    j2 = j;
                } else {
                    v2 = v1;
                    v1 = c;
                    j2 = j1;
                    j1 = j;
                }
            }
        }
        int i0 = y[j1];
        double v1_new = v[j1] - (v2 - v1);
        bool v1_lowers = v1_new < v[j1];
        if (rr_cnt < current * n) {
            if (v1_lowers) {
                v[j1] = v1_new;
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = y[j1];
            }
            if (i0 >= 0) {
                if (v1_lowers) {
                    free_rows[--current] = i0;  // retry immediately
                } else {
                    free_rows[new_free_rows++] = i0;
                }
            }
        } else {
            if (i0 >= 0) free_rows[new_free_rows++] = i0;
        }
        x[free_i] = j1;
        y[j1] = free_i;
    }
    return new_free_rows;
}

static int find_dense(int n, int lo, const double* d, int* cols) {
    int hi = lo + 1;
    double mind = d[cols[lo]];
    for (int k = hi; k < n; ++k) {
        int j = cols[k];
        if (d[j] <= mind) {
            if (d[j] < mind) {
                hi = lo;
                mind = d[j];
            }
            cols[k] = cols[hi];
            cols[hi++] = j;
        }
    }
    return hi;
}

static int scan_dense(int n, const double* cost, int& lo, int& hi, double* d, int* cols,
                      int* pred, const int* y, const double* v) {
    while (lo != hi) {
        int j = cols[lo++];
        int i = y[j];
        double mind = d[j];
        double h = cost[(size_t)i * n + j] - v[j] - mind;
        const double* row = cost + (size_t)i * n;
        for (int k = hi; k < n; ++k) {
            j = cols[k];
            double cred = row[j] - v[j] - h;
            if (cred < d[j]) {
                d[j] = cred;
                pred[j] = i;
                if (cred == mind) {
                    if (y[j] < 0) return j;
                    cols[k] = cols[hi];
                    cols[hi++] = j;
                }
            }
        }
    }
    return -1;
}

static int find_path_dense(int n, const double* cost, int start_i, int* y, double* v,
                           int* pred, int* cols, double* d) {
    int lo = 0, hi = 0;
    int final_j = -1;
    int n_ready = 0;
    const double* srow = cost + (size_t)start_i * n;
    for (int i = 0; i < n; ++i) {
        cols[i] = i;
        pred[i] = start_i;
        d[i] = srow[i] - v[i];
    }
    while (final_j == -1) {
        if (lo == hi) {
            n_ready = lo;
            hi = find_dense(n, lo, d, cols);
            for (int k = lo; k < hi; ++k) {
                int j = cols[k];
                if (y[j] < 0) final_j = j;
            }
        }
        if (final_j == -1) {
            final_j = scan_dense(n, cost, lo, hi, d, cols, pred, y, v);
        }
    }
    double mind = d[cols[lo]];
    for (int k = 0; k < n_ready; ++k) {
        int j = cols[k];
        v[j] += d[j] - mind;
    }
    return final_j;
}

static int ca_dense(int n, const double* cost, int n_free_rows, int* free_rows,
                    int* x, int* y, double* v) {
    std::vector<int> pred(n), cols(n);
    std::vector<double> d(n);
    for (int idx = 0; idx < n_free_rows; ++idx) {
        int free_i = free_rows[idx];
        int j = find_path_dense(n, cost, free_i, y, v, pred.data(), cols.data(), d.data());
        int i = -1;
        while (i != free_i) {
            i = pred[j];
            y[j] = i;
            int j_next = x[i];
            x[i] = j;
            j = j_next;
        }
    }
    return 0;
}

static void lapjv(int n, const double* cost, int* x) {
    std::vector<int> y(n), free_rows(n);
    std::vector<double> v(n);
    int n_free = ccrrt_dense(n, cost, free_rows.data(), x, y.data(), v.data());
    int it = 0;
    while (n_free > 0 && it < 2) {
        n_free = carr_dense(n, cost, n_free, free_rows.data(), x, y.data(), v.data());
        ++it;
    }
    if (n_free > 0) {
        ca_dense(n, cost, n_free, free_rows.data(), x, y.data(), v.data());
    }
}

