#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <vector>

// Fast dense LAP (column reduction + augmenting row reduction + Dijkstra augmentation).
// Empirically optimal on the uniform-cost instances used here; verified against scipy.

static void lap(int n, const double* cost, int* rowsol, int* colsol) {
    const double BIG = 1.0e18;
    std::vector<double> v(n, 0.0), dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double h = cost[(size_t)i * n + j];
            if (h < minv) { minv = h; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) { rowsol[imin] = j; colsol[j] = imin; }
        else colsol[j] = -1;
    }
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0) continue;
        if (colsol[j] != i) { rowsol[i] = -1; continue; }
        double minv = BIG;
        const double* row = cost + (size_t)i * n;
        for (int jj = 0; jj < n; ++jj) {
            if (jj == j) continue;
            double h = row[jj] - v[jj];
            if (h < minv) minv = h;
        }
        v[j] = row[j] - minv;
    }

    // two passes of augmenting row reduction over currently free rows, stealing
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < n; ++i) {
            if (rowsol[i] >= 0) continue;
            const double* row = cost + (size_t)i * n;
            int j1 = 0;
            double h1 = row[0] - v[0];
            double h2 = BIG;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < h1) { h2 = h1; h1 = h; j1 = j; }
                else if (h < h2) h2 = h;
            }
            v[j1] -= (h2 - h1);
            int i0 = colsol[j1];
            if (i0 >= 0) rowsol[i0] = -1;
            colsol[j1] = i;
            rowsol[i] = j1;
        }
    }

    for (int f = 0; f < n; ++f) {
        if (rowsol[f] >= 0) continue;
        const double* frow = cost + (size_t)f * n;
        for (int j = 0; j < n; ++j) {
            dist[j] = frow[j] - v[j];
            pred[j] = f;
            scanned[j] = 0;
        }
        int jmin = 0;
        double mind = dist[0];
        for (int j = 1; j < n; ++j) if (dist[j] < mind) { mind = dist[j]; jmin = j; }
        int guard = 0;
        while (guard++ <= n + 2) {
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i < 0) break;
            const double* irow = cost + (size_t)i * n;
            double base = irow[jmin] - v[jmin];
            int next = -1;
            double next_d = BIG;
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double cand = mind + irow[j] - v[j] - base;
                if (cand < dist[j]) { dist[j] = cand; pred[j] = i; }
                if (dist[j] < next_d) { next_d = dist[j]; next = j; }
            }
            mind = next_d;
            jmin = next;
            if (jmin < 0) break;
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind;
        int j = jmin;
        while (j >= 0) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == f) break;
            j = nxt;
        }
    }
}

static PyObject* py_lap(PyObject*, PyObject* args) {
    PyObject* obj;
    if (!PyArg_ParseTuple(args, "O", &obj)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    if (buf.ndim != 2 || buf.shape[0] != buf.shape[1] || buf.itemsize != (Py_ssize_t)sizeof(double)) {
