        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                tmp[(size_t)i * n + j] = *reinterpret_cast<const double*>(base + i * buf.strides[0] + j * buf.strides[1]);
        cost = tmp.data();
    }
