#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <vector>
#include <cmath>

// LAP with candidate columns = k nearest per row (union of row and column kNN built outside).
// cost is full n*n. cand is n*k int32, cand_k = k. cand[i*k + t] = column.
// If the optimum lies in the candidate graph this returns it; else may be infeasible (-2).

static int lap_cand(int n, int k, const double* cost, const int* cand, int* rowsol, int* colsol) {
    const double BIG = 1e18;
    std::vector<double> v(n, 0.0), dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n), is_cand_row(n);
    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    // column reduction over candidates only: for each col find min among rows that list it — expensive.
    // Instead initialize v[j] = min over all rows' candidate edges into j, fallback global min of column if none.
    std::vector<char> has(n, 0);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        const int* c = cand + (size_t)i * k;
        for (int t = 0; t < k; ++t) {
            int j = c[t];
            double h = row[j];
            if (!has[j] || h < v[j]) { v[j] = h; has[j] = 1; }
        }
    }
    // greedy match on candidates in order of reduced? simple: scan rows, take free best candidate
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        const int* c = cand + (size_t)i * k;
        int best = -1; double bh = BIG;
        for (int t = 0; t < k; ++t) {
            int j = c[t];
            if (colsol[j] >= 0) continue;
            double h = row[j] - v[j];
            if (h < bh) { bh = h; best = j; }
        }
        if (best >= 0) { rowsol[i] = best; colsol[best] = i; }
    }

    // augment free rows within candidate graph using Dijkstra over candidate edges of matched rows
    // Build reverse: for each col, list of rows that have it as candidate
    std::vector<int> rev_count(n, 0);
    for (int i = 0; i < n; ++i) {
        const int* c = cand + (size_t)i * k;
        for (int t = 0; t < k; ++t) rev_count[c[t]]++;
    }
    std::vector<int> rev_off(n + 1, 0);
    for (int j = 0; j < n; ++j) rev_off[j + 1] = rev_off[j] + rev_count[j];
    std::vector<int> rev(rev_off[n]);
    std::vector<int> cursor = rev_off;
    for (int i = 0; i < n; ++i) {
        const int* c = cand + (size_t)i * k;
        for (int t = 0; t < k; ++t) rev[cursor[c[t]]++] = i;
    }

    for (int f = 0; f < n; ++f) {
        if (rowsol[f] >= 0) continue;
        std::fill(dist.begin(), dist.end(), BIG);
        std::fill(scanned.begin(), scanned.end(), 0);
        const double* frow = cost + (size_t)f * n;
        const int* fc = cand + (size_t)f * k;
        double mind = BIG; int jmin = -1;
        for (int t = 0; t < k; ++t) {
            int j = fc[t];
            double h = frow[j] - v[j];
            dist[j] = h; pred[j] = f;
            if (h < mind) { mind = h; jmin = j; }
        }
        if (jmin < 0) return -2;
        int guard = 0;
        int endc = -1;
        while (guard++ < n + 2) {
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i < 0) { endc = jmin; break; }
            const double* irow = cost + (size_t)i * n;
            const int* ic = cand + (size_t)i * k;
            double base = irow[jmin] - v[jmin];
            int next = -1; double next_d = BIG;
            for (int t = 0; t < k; ++t) {
                int j = ic[t];
                if (scanned[j]) continue;
                double candv = mind + irow[j] - v[j] - base;
                if (candv < dist[j]) { dist[j] = candv; pred[j] = i; }
                if (dist[j] < next_d) { next_d = dist[j]; next = j; }
            }
            // also consider other unscanned cols already reached
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                if (dist[j] < next_d) { next_d = dist[j]; next = j; }
            }
            if (next < 0 || next_d >= BIG / 2) break;
            mind = next_d; jmin = next;
        }
        if (endc < 0) return -2;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind;
        int j = endc;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == f) break;
            j = nxt;
        }
    }
    return 0;
}

static PyObject* py_lap(PyObject*, PyObject* args) {
    PyObject *cost_obj, *cand_obj;
    if (!PyArg_ParseTuple(args, "OO", &cost_obj, &cand_obj)) return NULL;
    Py_buffer cb, kb;
    if (PyObject_GetBuffer(cost_obj, &cb, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    if (PyObject_GetBuffer(cand_obj, &kb, PyBUF_ND | PyBUF_STRIDES) != 0) { PyBuffer_Release(&cb); return NULL; }
    int n = (int)cb.shape[0];
    int k = (int)kb.shape[1];
    std::vector<double> cost((size_t)n * n);
    const char* base = (const char*)cb.buf;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cost[(size_t)i * n + j] = *reinterpret_cast<const double*>(base + i * cb.strides[0] + j * cb.strides[1]);
    std::vector<int> cand((size_t)n * k);
    const char* b2 = (const char*)kb.buf;
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < k; ++t) {
            // cand may be int64
            if (kb.itemsize == 8)
                cand[(size_t)i * k + t] = (int)*reinterpret_cast<const int64_t*>(b2 + i * kb.strides[0] + t * kb.strides[1]);
            else
                cand[(size_t)i * k + t] = *reinterpret_cast<const int32_t*>(b2 + i * kb.strides[0] + t * kb.strides[1]);
        }
    std::vector<int> rowsol(n), colsol(n);
    int rc = lap_cand(n, k, cost.data(), cand.data(), rowsol.data(), colsol.data());
    PyBuffer_Release(&cb); PyBuffer_Release(&kb);
    if (rc != 0) { PyErr_SetString(PyExc_RuntimeError, "infeasible"); return NULL; }
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(rowsol[i]));
    return list;
}
static PyMethodDef methods[] = {{"lap_cand", py_lap, METH_VARARGS, ""}, {NULL,NULL,0,NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "lap_knn", NULL, -1, methods};
PyMODINIT_FUNC PyInit_lap_knn(void) { return PyModule_Create(&moduledef); }
