#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <queue>
#include <vector>

struct Node {
    double d;
    int j;
    bool operator<(const Node& o) const { return d > o.d; }  // min-heap
};

static void lap(int n, int k, const double* cost, const int* knn, int* rowsol, int* colsol) {
    const double BIG = 1.0e18;
    std::vector<double> v(n, 0.0), dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double h = cost[(size_t)i * n + j];
            if (h < minv) { minv = h; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) { rowsol[imin] = j; colsol[j] = imin; }
        else colsol[j] = -1;
    }
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j < 0 || colsol[j] != i) { rowsol[i] = -1; continue; }
        double minv = BIG;
        const double* row = cost + (size_t)i * n;
        for (int jj = 0; jj < n; ++jj) {
            if (jj == j) continue;
            double h = row[jj] - v[jj];
            if (h < minv) minv = h;
        }
        v[j] = row[j] - minv;
    }
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < n; ++i) {
            if (rowsol[i] >= 0) continue;
            const double* row = cost + (size_t)i * n;
            int j1 = 0;
            double h1 = row[0] - v[0];
            double h2 = BIG;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < h1) { h2 = h1; h1 = h; j1 = j; }
                else if (h < h2) h2 = h;
            }
            v[j1] -= (h2 - h1);
            int i0 = colsol[j1];
            if (i0 >= 0) rowsol[i0] = -1;
            colsol[j1] = i;
            rowsol[i] = j1;
        }
    }

    // reverse kNN not needed; Dijkstra relaxes all columns but uses a heap,
    // and also preferentially scans knn edges first — still must be complete for correctness.
    // Heap Dijkstra over all n columns (decrease-key via duplicate pushes).
    for (int f = 0; f < n; ++f) {
        if (rowsol[f] >= 0) continue;
        const double* frow = cost + (size_t)f * n;
        for (int j = 0; j < n; ++j) {
            dist[j] = frow[j] - v[j];
            pred[j] = f;
            scanned[j] = 0;
        }
        std::priority_queue<Node> pq;
        for (int j = 0; j < n; ++j) pq.push({dist[j], j});
        int endc = -1;
        double mind = 0;
        while (!pq.empty()) {
            Node cur = pq.top(); pq.pop();
            int jmin = cur.j;
            if (scanned[jmin]) continue;
            if (cur.d > dist[jmin] + 1e-15) continue;
            scanned[jmin] = 1;
            mind = dist[jmin];
            int i = colsol[jmin];
            if (i < 0) { endc = jmin; break; }
            const double* irow = cost + (size_t)i * n;
            double base = irow[jmin] - v[jmin];
            // relax knn first (same result, just order)
            const int* ic = knn + (size_t)i * k;
            for (int t = 0; t < k; ++t) {
                int j = ic[t];
                if (scanned[j]) continue;
                double cand = mind + irow[j] - v[j] - base;
                if (cand < dist[j]) { dist[j] = cand; pred[j] = i; pq.push({cand, j}); }
            }
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double cand = mind + irow[j] - v[j] - base;
                if (cand < dist[j]) { dist[j] = cand; pred[j] = i; pq.push({cand, j}); }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind;
        int j = endc;
        while (j >= 0) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == f) break;
            j = nxt;
        }
    }
}

static PyObject* py_lap(PyObject*, PyObject* args) {
    PyObject *cost_obj, *knn_obj;
    if (!PyArg_ParseTuple(args, "OO", &cost_obj, &knn_obj)) return NULL;
    Py_buffer cb, kb;
    if (PyObject_GetBuffer(cost_obj, &cb, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    if (PyObject_GetBuffer(knn_obj, &kb, PyBUF_ND | PyBUF_STRIDES) != 0) { PyBuffer_Release(&cb); return NULL; }
    int n = (int)cb.shape[0];
    int k = (int)kb.shape[1];
    const double* cost = static_cast<const double*>(cb.buf);
    std::vector<int> knn((size_t)n * k);
    const char* b2 = (const char*)kb.buf;
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < k; ++t)
            knn[(size_t)i * k + t] = (int)*reinterpret_cast<const int64_t*>(b2 + i * kb.strides[0] + t * kb.strides[1]);
    std::vector<int> rowsol(n), colsol(n);
    lap(n, k, cost, knn.data(), rowsol.data(), colsol.data());
    PyBuffer_Release(&cb); PyBuffer_Release(&kb);
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(rowsol[i]));
    return list;
}
