#include <queue>
#include <vector>

struct Node { double d; int j; bool operator<(const Node& o) const { return d > o.d; } };

// Sparse LAP. For each row, cand[i*k + t] are candidate columns (t < deg[i]).
// Returns 0 on success, -1 if no augmenting path (candidates insufficient).
static int lap_sparse(int n, int k, const double* cost, const int* cand, const int* deg,
                      int* rowsol, int* colsol) {
    const double BIG = 1e18;
    std::vector<double> v(n, 0.0), dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol, colsol + n, -1);

    // init v[j] = min incoming candidate cost
    std::vector<char> has(n, 0);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int d = deg[i];
        const int* c = cand + (size_t)i * k;
        for (int t = 0; t < d; ++t) {
            int j = c[t];
            double h = row[j];
            if (!has[j] || h < v[j]) { v[j] = h; has[j] = 1; }
        }
    }
    // columns with no candidate edge: leave v=0

    // greedy
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int d = deg[i];
        const int* c = cand + (size_t)i * k;
        int best = -1; double bh = BIG;
        for (int t = 0; t < d; ++t) {
            int j = c[t];
            if (colsol[j] >= 0) continue;
            double h = row[j] - v[j];
            if (h < bh) { bh = h; best = j; }
        }
        if (best >= 0) { rowsol[i] = best; colsol[best] = i; }
    }

    for (int f = 0; f < n; ++f) {
        if (rowsol[f] >= 0) continue;
        std::fill(dist.begin(), dist.end(), BIG);
        std::fill(scanned.begin(), scanned.end(), 0);
        const double* frow = cost + (size_t)f * n;
        int fd = deg[f];
        const int* fc = cand + (size_t)f * k;
        std::priority_queue<Node> pq;
        for (int t = 0; t < fd; ++t) {
            int j = fc[t];
            dist[j] = frow[j] - v[j];
            pred[j] = f;
            pq.push({dist[j], j});
        }
        int endc = -1;
        double mind = 0;
        while (!pq.empty()) {
            Node cur = pq.top(); pq.pop();
            int jmin = cur.j;
            if (scanned[jmin] || cur.d > dist[jmin] + 1e-12) continue;
            scanned[jmin] = 1;
            mind = dist[jmin];
            int i = colsol[jmin];
            if (i < 0) { endc = jmin; break; }
            const double* irow = cost + (size_t)i * n;
            double base = irow[jmin] - v[jmin];
            int id = deg[i];
            const int* ic = cand + (size_t)i * k;
            for (int t = 0; t < id; ++t) {
                int j = ic[t];
                if (scanned[j]) continue;
                double candv = mind + irow[j] - v[j] - base;
                if (candv < dist[j]) { dist[j] = candv; pred[j] = i; pq.push({candv, j}); }
            }
        }
        if (endc < 0) return -1;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind;
        int j = endc;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == f) break;
            j = nxt;
        }
    }
    return 0;
}

static PyObject* py_lap(PyObject*, PyObject* args) {
    PyObject *cost_obj, *cand_obj, *deg_obj;
    if (!PyArg_ParseTuple(args, "OOO", &cost_obj, &cand_obj, &deg_obj)) return NULL;
    Py_buffer cb, kb, db;
    if (PyObject_GetBuffer(cost_obj, &cb, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    if (PyObject_GetBuffer(cand_obj, &kb, PyBUF_ND | PyBUF_STRIDES) != 0) { PyBuffer_Release(&cb); return NULL; }
    if (PyObject_GetBuffer(deg_obj, &db, PyBUF_ND | PyBUF_STRIDES) != 0) { PyBuffer_Release(&cb); PyBuffer_Release(&kb); return NULL; }
    int n = (int)cb.shape[0];
    int k = (int)kb.shape[1];
    std::vector<int> cand((size_t)n * k), deg(n), rowsol(n), colsol(n);
    const char* b2 = (const char*)kb.buf;
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < k; ++t)
            cand[(size_t)i * k + t] = (int)*reinterpret_cast<const int64_t*>(b2 + i * kb.strides[0] + t * kb.strides[1]);
    const char* bd = (const char*)db.buf;
    for (int i = 0; i < n; ++i)
        deg[i] = (int)*reinterpret_cast<const int64_t*>(bd + i * db.strides[0]);
    int rc = lap_sparse(n, k, static_cast<const double*>(cb.buf), cand.data(), deg.data(), rowsol.data(), colsol.data());
    PyBuffer_Release(&cb); PyBuffer_Release(&kb); PyBuffer_Release(&db);
    if (rc != 0) { PyErr_SetString(PyExc_RuntimeError, "no path"); return NULL; }
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(rowsol[i]));
    return list;
}
