#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <vector>

// Hungarian (Kuhn-Munkres) restricted to a candidate edge set.
// cost is full n*n float64. cand is n*k int64 columns, deg[i] valid count.
// If the optimum's edges are all candidates, the result is optimal.
// Returns -1 if the candidate graph has no perfect matching.

static int hungarian_sparse(int n, int k, const double* cost, const int* cand, const int* deg, int* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n + 1, 0.0), v(n + 1, 0.0), minv(n + 1);
    std::vector<int> p(n + 1, 0), way(n + 1, 0);
    std::vector<char> used(n + 1);
    // adjacency: row i (1-based i) candidates are cand[(i-1)*k + t] + 1
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        std::fill(minv.begin(), minv.end(), INF);
        std::fill(used.begin(), used.end(), 0);
        int di = deg[i - 1];
        const int* ci = cand + (size_t)(i - 1) * k;
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = 0;
            const int* crow = cand + (size_t)(i0 - 1) * k;
            int d0 = deg[i0 - 1];
            // only candidate columns of row i0 can improve
            // But minv of non-candidates stays INF and is never selected if any candidate exists.
            for (int t = 0; t < d0; ++t) {
                int j = crow[t] + 1;  // 1-based
                if (used[j]) continue;
                double cur = cost[(size_t)(i0 - 1) * n + (j - 1)] - u[i0] - v[j];
                if (cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            // also need the global min among already-touched columns' minv, including ones not
            // updated this iteration. The classic algorithm scans ALL columns. Columns never
            // reached keep INF. Among reached, minv was set previously and decreased.
            // We must consider all columns' minv, not only this row's candidates.
            for (int j = 1; j <= n; ++j) {
                if (used[j]) continue;
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            if (j1 == 0) return -1;  // no admissible column
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }
    for (int j = 1; j <= n; ++j) col_of_row[p[j] - 1] = j - 1;
    return 0;
}

