#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <vector>
#include <cmath>

// Epsilon-scaling auction for the assignment problem (minimization).
// Returns row->col. For small enough final epsilon this is optimal on generic costs.

static void auction(int n, const double* cost, int* assignment, double eps_final, double eps_factor) {
    const double NEG = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::fill(assignment, assignment + n, -1);

    double cmax = 0.0;
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = std::max(cmax, 1e-6);

    std::vector<int> free_rows(n);
    while (eps > eps_final) {
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
        int nf = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        const int guard_max = n * n * 2;
        while (nf > 0 && guard++ < guard_max) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                if (assignment[i] >= 0) continue;
                const double* row = cost + (size_t)i * n;
                int j1 = 0;
                double v1 = -row[0] - price[0];
                double v2 = NEG;
                for (int j = 1; j < n; ++j) {
                    double v = -row[j] - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                double bid = price[j1] + (v1 - v2) + eps;
                int prev = owner[j1];
                if (prev >= 0) {
                    assignment[prev] = -1;
                    free_rows[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
        }
        if (eps <= eps_final) break;
    }
}

static PyObject* py_auction(PyObject*, PyObject* args) {
    PyObject* obj;
    double eps_final = 1e-9;
    double factor = 0.25;
    if (!PyArg_ParseTuple(args, "O|dd", &obj, &eps_final, &factor)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    int n = (int)buf.shape[0];
    const double* cost = static_cast<const double*>(buf.buf);
    std::vector<int> asg(n);
    auction(n, cost, asg.data(), eps_final, factor);
    PyBuffer_Release(&buf);
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(asg[i]));
    return list;
}
