        int d = deg[i];
        const int* c = cand + (size_t)i * k;
        for (int t = 0; t < d; ++t) if (row[c[t]] > cmax) cmax = row[c[t]];
    }
    double eps = std::max(cmax, 1e-6);
    std::vector<int> free_rows(n), next_free(n);
    bool first = true;
    while (true) {
        if (!first) eps *= eps_factor;
        first = false;
        if (eps < eps_final) eps = eps_final;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
        int nf = n;
