        const int guard_max = n * 400;
        while (nf > 0 && guard++ < guard_max) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                const double* row = cost + (size_t)i * n;
                int d = deg[i];
                const int* c = cand + (size_t)i * k;
                if (d == 0) return -1;
                int j1 = c[0];
