                double v2 = NEG;
                for (int t = 1; t < d; ++t) {
                    int j = c[t];
                    double v = -row[j] - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                if (v2 <= NEG / 2) v2 = v1 - 1.0;  // single candidate
                double bid = price[j1] + (v1 - v2) + eps;
