import numpy as np, time, auction_ext, ot
from reference import Task

def cands(M, thr, kmax=256):
    n=M.shape[0]
    # vectorized: for each row, indices where M<=thr. degrees vary.
    mask = M <= thr
    deg = mask.sum(axis=1)
    k = int(min(kmax, deg.max()))
    cand = np.full((n, k), -1, np.int64)
    # fill
    for i in range(n):
        js = np.flatnonzero(mask[i])
        if len(js) > k:
            js = js[np.argpartition(M[i, js], k-1)[:k]]
        cand[i, :len(js)] = js
    return cand, deg.astype(np.int64)

task=Task()
for seed in range(4):
    p=task.generate_problem(n=600, random_seed=14000+seed)
    M=np.ascontiguousarray(p["cost_matrix"], dtype=np.float64)
    t0=time.perf_counter(); G=ot.lp.emd(p["source_weights"], p["target_weights"], M, check_marginals=False); tot=time.perf_counter()-t0
    otc=np.argmax(G,1)
    for thr in (0.2, 0.25):
        t0=time.perf_counter(); cand, deg = cands(M, thr); tb=time.perf_counter()-t0
        t0=time.perf_counter()
        try:
            a=np.array(auction_ext.auction(M, cand, deg, 1e-9, 0.25))
            dt=time.perf_counter()-t0
            print(seed, "thr", thr, "build", round(tb*1000,1), "solve", round(dt*1000,1), "ot", round(tot*1000,1),
                  "same", np.array_equal(a, otc), "deg", round(deg.mean(),1))
        except Exception as e:
            print(seed, thr, "FAIL", e)
