// Standalone LAPJV (Jonker-Volgenant), following gatagat/lap lapjv.h dense path.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <random>
#include <vector>

using clk = std::chrono::steady_clock;

template <class T>
struct Solver {
    int n;
    const T* cost;  // row-major
    std::vector<int> x, y, free_rows, pred, cols;
    std::vector<T> v, d;
    static constexpr T LARGE = 1e18;

    T C(int i, int j) const { return cost[(size_t)i * n + j]; }

    int ccrrt() {
        std::fill(x.begin(), x.end(), -1);
        std::fill(v.begin(), v.end(), LARGE);
        std::fill(y.begin(), y.end(), 0);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                T c = C(i, j);
                if (c < v[j]) { v[j] = c; y[j] = i; }
            }
        }
        std::vector<char> unique(n, 1);
        for (int j = n - 1; j >= 0; --j) {
            int i = y[j];
            if (x[i] < 0) x[i] = j;
            else { unique[i] = 0; y[j] = -1; }
        }
        int n_free = 0;
        for (int i = 0; i < n; ++i) {
            if (x[i] < 0) free_rows[n_free++] = i;
            else if (unique[i]) {
                int j = x[i];
                T minv = LARGE;
                for (int j2 = 0; j2 < n; ++j2) {
                    if (j2 == j) continue;
                    T c = C(i, j2) - v[j2];
                    if (c < minv) minv = c;
                }
                v[j] -= minv;
            }
        }
        return n_free;
    }

    int carr(int n_free_rows) {
        int current = 0, new_free = 0, rr_cnt = 0;
        while (current < n_free_rows) {
            rr_cnt++;
            int free_i = free_rows[current++];
            int j1 = 0, j2 = -1;
            T v1 = C(free_i, 0) - v[0], v2 = LARGE;
            for (int j = 1; j < n; ++j) {
                T c = C(free_i, j) - v[j];
                if (c < v2) {
                    if (c >= v1) { v2 = c; j2 = j; }
                    else { v2 = v1; v1 = c; j2 = j1; j1 = j; }
                }
            }
            int i0 = y[j1];
            T v1_new = v[j1] - (v2 - v1);
            bool v1_lowers = v1_new < v[j1];
            if (rr_cnt < current * n) {
                if (v1_lowers) v[j1] = v1_new;
                else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = y[j1]; }
                if (i0 >= 0) {
                    if (v1_lowers) free_rows[--current] = i0;
                    else free_rows[new_free++] = i0;
                }
            } else if (i0 >= 0) {
                free_rows[new_free++] = i0;
            }
            x[free_i] = j1;
            y[j1] = free_i;
        }
        return new_free;
    }

    int find_dense(int lo) {
        int hi = lo + 1;
        T mind = d[cols[lo]];
        for (int k = hi; k < n; ++k) {
            int j = cols[k];
            if (d[j] <= mind) {
                if (d[j] < mind) { hi = lo; mind = d[j]; }
                cols[k] = cols[hi];
                cols[hi++] = j;
            }
        }
        return hi;
    }

    int scan_dense(int& lo, int& hi) {
        while (lo != hi) {
            int j = cols[lo++];
            int i = y[j];
            T mind = d[j];
            T h = C(i, j) - v[j] - mind;
            for (int k = hi; k < n; ++k) {
                j = cols[k];
                T cred = C(i, j) - v[j] - h;
                if (cred < d[j]) {
                    d[j] = cred;
                    pred[j] = i;
                    if (cred == mind) {
                        if (y[j] < 0) return j;
                        cols[k] = cols[hi];
                        cols[hi++] = j;
                    }
                }
            }
        }
        return -1;
    }

    int find_path(int start_i) {
        int lo = 0, hi = 0, final_j = -1, n_ready = 0;
        for (int i = 0; i < n; ++i) {
            cols[i] = i;
            pred[i] = start_i;
            d[i] = C(start_i, i) - v[i];
        }
        while (final_j == -1) {
            if (lo == hi) {
                n_ready = lo;
                hi = find_dense(lo);
                for (int k = lo; k < hi; ++k) {
                    int j = cols[k];
                    if (y[j] < 0) final_j = j;
                }
            }
            if (final_j == -1) final_j = scan_dense(lo, hi);
        }
        T mind = d[cols[lo]];
        for (int k = 0; k < n_ready; ++k) v[cols[k]] += d[cols[k]] - mind;
        return final_j;
    }

    void augment(int n_free) {
        for (int idx = 0; idx < n_free; ++idx) {
            int free_i = free_rows[idx];
            int j = find_path(free_i);
            int i = -1;
            while (i != free_i) {
                i = pred[j];
                y[j] = i;
                int jn = x[i];
                x[i] = j;
                j = jn;
            }
        }
    }

    void solve() {
        int nf = ccrrt();
        int it = 0;
        while (nf > 0 && it < 2) { nf = carr(nf); ++it; }
        if (nf > 0) augment(nf);
    }
};

int main() {
    int n = 600;
    std::mt19937 rng(1);
    std::uniform_real_distribution<double> dist(0.0, 1.0);
    std::vector<double> S(n * 2), T(n * 2);
    for (int i = 0; i < n * 2; ++i) { S[i] = dist(rng); T[i] = dist(rng); }
    std::vector<double> cost((size_t)n * n);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double dx = S[2 * i] - T[2 * j], dy = S[2 * i + 1] - T[2 * j + 1];
            cost[(size_t)i * n + j] = std::sqrt(dx * dx + dy * dy);
        }
    Solver<double> s;
    s.n = n; s.cost = cost.data();
    s.x.resize(n); s.y.resize(n); s.free_rows.resize(n); s.pred.resize(n); s.cols.resize(n);
    s.v.resize(n); s.d.resize(n);
    auto t0 = clk::now();
    s.solve();
    auto t1 = clk::now();
    std::vector<char> seen(n, 0);
    int bad = 0; double csum = 0;
    for (int i = 0; i < n; ++i) {
        int j = s.x[i];
        if (j < 0 || j >= n || seen[j]) bad++;
        else seen[j] = 1;
        if (j >= 0 && j < n) csum += cost[(size_t)i * n + j];
    }
    std::cout << "ms " << std::chrono::duration<double, std::milli>(t1 - t0).count()
              << " bad " << bad << " cost " << csum << "\n";
    // second timing
    t0 = clk::now(); s.solve(); t1 = clk::now();
    std::cout << "ms2 " << std::chrono::duration<double, std::milli>(t1 - t0).count() << "\n";
}
