#include <Python.h>
#include <immintrin.h>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>

// Dense epsilon-scaling auction, AVX2 inner scan.
// Returns row->col assignment. On exit, *certified is 1 if the final prices
// prove the assignment is the unique optimum.

static inline void scan_row_avx(const double* row, const double* price, int n,
                                int& j1, double& v1, double& v2) {
    const __m256d sign = _mm256_set1_pd(-1.0);
    __m256d bestv = _mm256_set1_pd(-1e300);
    __m256d bestj = _mm256_set1_pd(0.0);
    __m256d secondv = _mm256_set1_pd(-1e300);
    int j = 0;
    for (; j + 4 <= n; j += 4) {
        __m256d c = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d v = _mm256_sub_pd(_mm256_mul_pd(sign, c), p);  // -c - p
        __m256d idx = _mm256_set_pd((double)(j + 3), (double)(j + 2), (double)(j + 1), (double)j);
        // lanes better than best
        __m256d gt = _mm256_cmp_pd(v, bestv, _CMP_GT_OQ);
        // new second = max(old second, blend(old best where gt else nothing), blend(v where not gt))
        __m256d old_best_demoted = _mm256_blendv_pd(secondv, bestv, gt);
        __m256d v_if_not = _mm256_blendv_pd(v, secondv, gt);
        secondv = _mm256_max_pd(old_best_demoted, v_if_not);
        bestv = _mm256_blendv_pd(bestv, v, gt);
        bestj = _mm256_blendv_pd(bestj, idx, gt);
        // if v equals best and we didn't take it as strictly greater, it can be second — already handled
    }
    // horizontal reduce 4 lanes into scalar top-2
    alignas(32) double bv[4], sv[4], bj[4];
    _mm256_store_pd(bv, bestv);
    _mm256_store_pd(sv, secondv);
    _mm256_store_pd(bj, bestj);
    v1 = -1e300; v2 = -1e300; j1 = 0;
    for (int t = 0; t < 4; ++t) {
        if (bv[t] > v1) { v2 = v1; v1 = bv[t]; j1 = (int)bj[t]; }
        else if (bv[t] > v2) v2 = bv[t];
        if (sv[t] > v2 && sv[t] < v1) v2 = sv[t];
        else if (sv[t] > v2 && (int)bj[t] != j1) v2 = sv[t];
    }
    for (; j < n; ++j) {
        double v = -row[j] - price[j];
        if (v > v1) { v2 = v1; v1 = v; j1 = j; }
        else if (v > v2) v2 = v;
    }
}

static int auction(int n, const double* cost, int* assignment, double* price_out,
                   double eps_final, double eps_factor) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::fill(assignment, assignment + n, -1);
    double cmax = 0.0;
    for (size_t i = 0, N = (size_t)n * n; i < N; i += 8) {
        // sample-ish full scan is fine once
    }
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax;
    std::vector<int> free_rows(n), next_free(n);
    int phases = 0;
    while (eps > eps_final * 0.999) {
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
        int nf = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        const int guard_max = n * 8;
        while (nf > 0 && guard++ < guard_max) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                int j1; double v1, v2;
                scan_row_avx(cost + (size_t)i * n, price.data(), n, j1, v1, v2);
                double bid = price[j1] + (v1 - v2) + eps;
                int prev = owner[j1];
                if (prev >= 0) {
                    assignment[prev] = -1;
                    next_free[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
            if (nf) std::memcpy(free_rows.data(), next_free.data(), nf * sizeof(int));
        }
        if (nf > 0) return -1;
        ++phases;
        if (eps <= eps_final) break;
        if (phases > 60) break;
    }
    if (price_out) std::memcpy(price_out, price.data(), n * sizeof(double));
    return 0;
}

// Certificate: assigned column is the unique minimizer of cost - dual for every row.
// We stored auction prices on the benefit side (price increases). Benefit = -cost - price.
// Assigned j maximizes -cost - price, i.e. minimizes cost + price.
// Unique if the second-best benefit is strictly worse by margin.
static int certify(int n, const double* cost, const int* asg, const double* price, double margin) {
    for (int i = 0; i < n; ++i) {
        int j1; double v1, v2;
        scan_row_avx(cost + (size_t)i * n, price, n, j1, v1, v2);
        if (j1 != asg[i]) return 0;
        if (v1 - v2 < margin) return 0;
    }
    return 1;
}

static PyObject* py_solve(PyObject*, PyObject* args) {
    PyObject* obj;
    double eps_final = 1e-9;
    double factor = 0.5;
    if (!PyArg_ParseTuple(args, "O|dd", &obj, &eps_final, &factor)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    int n = (int)buf.shape[0];
    if (buf.strides[0] != (Py_ssize_t)n * (Py_ssize_t)sizeof(double) || buf.strides[1] != (Py_ssize_t)sizeof(double)) {
        PyBuffer_Release(&buf);
        PyErr_SetString(PyExc_ValueError, "need C-contiguous float64");
        return NULL;
    }
    std::vector<int> asg(n);
    std::vector<double> price(n);
    int rc = auction(n, static_cast<const double*>(buf.buf), asg.data(), price.data(), eps_final, factor);
    int cert = 0;
    if (rc == 0) cert = certify(n, static_cast<const double*>(buf.buf), asg.data(), price.data(), 1e-8);
    PyBuffer_Release(&buf);
    if (rc != 0) { PyErr_SetString(PyExc_RuntimeError, "auction failed"); return NULL; }
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(asg[i]));
    return Py_BuildValue("Ni", list, cert);
}

static PyMethodDef methods[] = {{"solve", py_solve, METH_VARARGS, ""}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "auction_ext", NULL, -1, methods};
PyMODINIT_FUNC PyInit_auction_ext(void) { return PyModule_Create(&moduledef); }
