#include <Python.h>
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <vector>
#include <cmath>

// Forward auction that keeps the partial matching across epsilon phases.
// Only currently unassigned rows bid. Prices never decrease, so a matched
// person stays matched until outbid.

static void auction(int n, const double* cost, int* assignment, double eps_final, double eps_factor) {
    const double NEG = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::fill(assignment, assignment + n, -1);
    double cmax = 0.0;
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax;
    std::vector<int> free_rows(n), next_free(n);
    int nf = n;
    for (int i = 0; i < n; ++i) free_rows[i] = i;

    int phases = 0;
    while (eps > eps_final * 0.5) {
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
        // everyone not currently assigned must bid; at phase start that's `free_rows`
        int guard = 0;
        const int guard_max = n * 30;
        while (nf > 0 && guard++ < guard_max) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                const double* row = cost + (size_t)i * n;
                int j1 = 0;
                double v1 = -row[0] - price[0];
                double v2 = NEG;
                for (int j = 1; j < n; ++j) {
                    double v = -row[j] - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                double bid = price[j1] + (v1 - v2) + eps;
                // only displace if we actually raise the price (always true by +eps unless same)
                int prev = owner[j1];
                if (prev == i) {
                    price[j1] = bid;
                    continue;
                }
                if (prev >= 0) {
                    assignment[prev] = -1;
                    next_free[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
            if (nf) std::memcpy(free_rows.data(), next_free.data(), nf * sizeof(int));
        }
        ++phases;
        if (eps <= eps_final) break;
        if (phases > 80) break;
        // next phase: all currently unassigned (should be none if previous converged)
        // plus, to refine, unassign everyone and keep prices — standard scaling.
        // Keeping prices, restart matching from scratch is the proven approach and
        // converges faster because prices are warm. Do that.
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
        nf = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
    }
}

