    PyObject* obj;
    double eps_final = 1e-8;
    double factor = 0.25;
    if (!PyArg_ParseTuple(args, "O|dd", &obj, &eps_final, &factor)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    int n = (int)buf.shape[0];
    std::vector<int> asg(n);
    auction(n, static_cast<const double*>(buf.buf), asg.data(), eps_final, factor);
    PyBuffer_Release(&buf);
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(asg[i]));
    return list;
}
