#include <Python.h>
#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <thread>
#include <vector>

// Parallel epsilon-scaling auction. Row scans are independent within a round
// and are split across a persistent thread pool; bids are applied serially.

static int NTHREADS = 6;

struct Pool {
    int n = 0;
    const double* cost = nullptr;
    const double* price = nullptr;
    const int* rows = nullptr;  // free row indices
    int nf = 0;
    std::vector<int> bid_j;
    std::vector<double> bid_val;
    std::atomic<int> cursor{0};
    std::atomic<int> done{0};
    std::atomic<int> epoch{0};
    std::atomic<bool> stop{false};
    std::vector<std::thread> threads;

    void worker() {
        int seen = 0;
        while (!stop.load(std::memory_order_relaxed)) {
            int e = epoch.load(std::memory_order_acquire);
            if (e == seen) {
                std::this_thread::yield();
                continue;
            }
            seen = e;
            const double NEG = -1e300;
            while (true) {
                int kf = cursor.fetch_add(1, std::memory_order_relaxed);
                if (kf >= nf) break;
                int i = rows[kf];
                const double* row = cost + (size_t)i * n;
                int j1 = 0;
                double v1 = -row[0] - price[0];
                double v2 = NEG;
                for (int j = 1; j < n; ++j) {
                    double v = -row[j] - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                bid_j[i] = j1;
                bid_val[i] = v1 - v2;  // increment over current price[j1]
            }
            done.fetch_add(1, std::memory_order_release);
        }
    }

    void start(int nthreads) {
        threads.reserve(nthreads);
        for (int t = 0; t < nthreads; ++t) threads.emplace_back([this] { worker(); });
    }
    ~Pool() {
        stop.store(true);
        epoch.fetch_add(1);  // wake
        for (auto& t : threads) if (t.joinable()) t.join();
    }
    void scan(int n_, const double* cost_, const double* price_, const int* rows_, int nf_,
              int* out_j, double* out_inc) {
        n = n_; cost = cost_; price = price_; rows = rows_; nf = nf_;
        if ((int)bid_j.size() < n) { bid_j.resize(n); bid_val.resize(n); }
        cursor.store(0, std::memory_order_relaxed);
        done.store(0, std::memory_order_relaxed);
        epoch.fetch_add(1, std::memory_order_release);
        int need = (int)threads.size();
        while (done.load(std::memory_order_acquire) < need) std::this_thread::yield();
        for (int kf = 0; kf < nf; ++kf) {
            int i = rows[kf];
            out_j[kf] = bid_j[i];
            out_inc[kf] = bid_val[i];
        }
    }
};

static Pool* pool = nullptr;

static void auction(int n, const double* cost, int* assignment, double eps_final, double eps_factor) {
    std::vector<double> price(n, 0.0);
