#include <Python.h>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>

// Epsilon-scaling forward auction (Bertsekas). Prices and the matching persist
// across phases; only epsilon-CS violators are unassigned when epsilon shrinks.

struct Result { int rounds; int phases; };

static Result auction(int n, const double* cost, int* assignment, double eps_final, double eps_factor) {
    const double NEG = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::fill(assignment, assignment + n, -1);

    double cmax = 0.0;
    for (size_t t = 0, N = (size_t)n * n; t < N; ++t) if (cost[t] > cmax) cmax = cost[t];

    std::vector<int> free_rows(n), next_free(n);
    int nf = n;
    for (int i = 0; i < n; ++i) free_rows[i] = i;

    double eps = cmax;
    int total_rounds = 0, phases = 0;

    auto bidding_round = [&](int& nf_) {
        int new_nf = 0;
        for (int kf = 0; kf < nf_; ++kf) {
            int i = free_rows[kf];
            const double* row = cost + (size_t)i * n;
            int j1 = 0;
            double v1 = -row[0] - price[0];
            double v2 = NEG;
            for (int j = 1; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                else if (v > v2) v2 = v;
            }
            double bid = price[j1] + (v1 - v2) + eps;
            int prev = owner[j1];
            if (prev == i) { price[j1] = bid; continue; }
            if (prev >= 0) {
                assignment[prev] = -1;
                next_free[new_nf++] = prev;
            }
            owner[j1] = i;
            assignment[i] = j1;
            price[j1] = bid;
        }
        nf_ = new_nf;
        if (nf_) std::memcpy(free_rows.data(), next_free.data(), nf_ * sizeof(int));
    };

    while (true) {
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
        ++phases;
        int guard = 0;
        while (nf > 0 && guard < n * 100) {
            bidding_round(nf);
            ++guard;
            ++total_rounds;
        }
        if (eps <= eps_final) break;
        // tighten: unassign rows that violate epsilon-CS at the new epsilon
        double next_eps = eps * eps_factor;
        if (next_eps < eps_final) next_eps = eps_final;
        nf = 0;
        for (int i = 0; i < n; ++i) {
            int jstar = assignment[i];
            const double* row = cost + (size_t)i * n;
            double vstar = (jstar >= 0) ? (-row[jstar] - price[jstar]) : NEG;
            double best = NEG;
            for (int j = 0; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v > best) best = v;
            }
            if (jstar < 0 || vstar < best - next_eps) {
                if (jstar >= 0) { owner[jstar] = -1; assignment[i] = -1; }
                free_rows[nf++] = i;
            }
        }
    }
    Result r{total_rounds, phases};
    return r;
}

static PyObject* py_auction(PyObject*, PyObject* args) {
    PyObject* obj; double eps_final=1e-9, factor=0.25;
    if (!PyArg_ParseTuple(args, "O|dd", &obj, &eps_final, &factor)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    int n = (int)buf.shape[0];
    std::vector<int> asg(n);
    Result r = auction(n, (const double*)buf.buf, asg.data(), eps_final, factor);
    PyBuffer_Release(&buf);
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(asg[i]));
    return Py_BuildValue("Nii", list, r.rounds, r.phases);
}
static PyMethodDef methods[]={{"auction", py_auction, METH_VARARGS,""},{NULL,NULL,0,NULL}};
static struct PyModuleDef moduledef={PyModuleDef_HEAD_INIT,"auction_ext",NULL,-1,methods};
PyMODINIT_FUNC PyInit_auction_ext(void){return PyModule_Create(&moduledef);}
