#include <Python.h>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>

// Thresholded epsilon-scaling auction with a full-matrix optimality certificate.
// Edges longer than `thr` are omitted; any column that violates epsilon-complementary
// slackness is added and the auction is repeated. For a small enough final epsilon
// the certified assignment is the unique optimum of the dense problem.

static constexpr double NEG = -1e300;

struct Graph {
    int n, kcap;
    std::vector<int> cand;  // n * kcap
    std::vector<int> deg;
    Graph(int n_, int kcap_) : n(n_), kcap(kcap_), cand((size_t)n_ * kcap_, -1), deg(n_, 0) {}
    void add(int i, int j) {
        int d = deg[i];
        int* row = cand.data() + (size_t)i * kcap;
        for (int t = 0; t < d; ++t) if (row[t] == j) return;
        if (d >= kcap) return;  // saturated; caller should raise kcap
        row[d] = j;
        deg[i] = d + 1;
    }
};

static void build_threshold(Graph& g, const double* cost, double thr) {
    int n = g.n;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int d = 0;
        int* out = g.cand.data() + (size_t)i * g.kcap;
        for (int j = 0; j < n; ++j) {
            if (row[j] <= thr) {
                if (d < g.kcap) out[d++] = j;
            }
        }
        g.deg[i] = d;
    }
}

// Returns number of bidding rounds, or -1 on failure.
static int auction_on(const Graph& g, const double* cost, std::vector<double>& price,
                      std::vector<int>& owner, int* assignment, double eps_final, double eps_factor,
                      bool reset_prices) {
    int n = g.n;
    if (reset_prices) {
        std::fill(price.begin(), price.end(), 0.0);
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
    }
    double cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        const int* c = g.cand.data() + (size_t)i * g.kcap;
        int d = g.deg[i];
        for (int t = 0; t < d; ++t) if (row[c[t]] > cmax) cmax = row[c[t]];
    }
    double eps = std::max(cmax, 1e-6);
    std::vector<int> free_rows(n), next_free(n);
    int total_rounds = 0;
    bool first = true;
    while (true) {
        if (!first) eps *= eps_factor;
        first = false;
        if (eps < eps_final) eps = eps_final;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
        int nf = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        const int guard_max = n * 200;
        while (nf > 0 && guard++ < guard_max) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                const double* row = cost + (size_t)i * n;
                const int* c = g.cand.data() + (size_t)i * g.kcap;
                int d = g.deg[i];
                if (d <= 0) return -1;
                int j1 = c[0];
                double v1 = -row[j1] - price[j1];
                double v2 = NEG;
                for (int t = 1; t < d; ++t) {
                    int j = c[t];
                    double v = -row[j] - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                if (d == 1) v2 = v1 - 1.0;
                double bid = price[j1] + (v1 - v2) + eps;
                int prev = owner[j1];
                if (prev >= 0) {
                    assignment[prev] = -1;
                    next_free[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
            if (nf) std::memcpy(free_rows.data(), next_free.data(), nf * sizeof(int));
            ++total_rounds;
        }
        if (nf > 0) return -1;
        if (eps <= eps_final) break;
    }
    return total_rounds;
}

// Add every column that beats the assigned column by more than margin. Returns count added.
static int add_violators(Graph& g, const double* cost, const double* price, const int* assignment, double margin) {
    int n = g.n;
    int added = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int jstar = assignment[i];
        double vstar = -row[jstar] - price[jstar];
        int jbest = jstar;
        double vbest = vstar;
        for (int j = 0; j < n; ++j) {
            double v = -row[j] - price[j];
            if (v > vbest) { vbest = v; jbest = j; }
        }
        if (vbest > vstar + margin) {
            int before = g.deg[i];
            g.add(i, jbest);
            if (g.deg[i] > before) ++added;
            // also add a few near-best to help the next auction
        }
    }
    return added;
}

static int solve(int n, const double* cost, int* assignment, double thr, double eps_final) {
    int kcap = std::min(n, 400);
    Graph g(n, kcap);
    build_threshold(g, cost, thr);
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    for (int round = 0; round < 8; ++round) {
        int rc = auction_on(g, cost, price, owner, assignment, eps_final, 0.25, true);
        if (rc < 0) {
            // candidate graph has no perfect matching; widen threshold
            thr *= 1.4;
            if (thr > 2.0) return -1;
            g = Graph(n, kcap);
            build_threshold(g, cost, thr);
            continue;
        }
        int added = add_violators(g, cost, price.data(), assignment, eps_final);
        if (added == 0) return 0;
    }
    return -1;
}

static PyObject* py_solve(PyObject*, PyObject* args) {
    PyObject* obj;
    double thr = 0.25;
    double eps = 1e-9;
    if (!PyArg_ParseTuple(args, "O|dd", &obj, &thr, &eps)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    int n = (int)buf.shape[0];
    if (buf.ndim != 2 || buf.shape[1] != n || buf.itemsize != (Py_ssize_t)sizeof(double)
        || buf.strides[1] != (Py_ssize_t)sizeof(double)
        || buf.strides[0] != n * (Py_ssize_t)sizeof(double)) {
        PyBuffer_Release(&buf);
        PyErr_SetString(PyExc_ValueError, "need square C-contiguous float64");
        return NULL;
    }
    std::vector<int> asg(n, -1);
    int rc = solve(n, (const double*)buf.buf, asg.data(), thr, eps);
    PyBuffer_Release(&buf);
    if (rc != 0) {
        PyErr_SetString(PyExc_RuntimeError, "failed to certify");
        return NULL;
    }
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(asg[i]));
    return list;
}

static PyMethodDef methods[] = {{"solve", py_solve, METH_VARARGS, ""}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "emd_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_emd_fast(void) { return PyModule_Create(&moduledef); }
