#include <Python.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>

static constexpr double NEG = -1e300;

struct Graph {
    int n, kcap;
    std::vector<int> cand, deg;
    Graph(int n_, int kcap_) : n(n_), kcap(kcap_), cand((size_t)n_ * kcap_, -1), deg(n_, 0) {}
    void add(int i, int j) {
        int d = deg[i];
        int* row = cand.data() + (size_t)i * kcap;
        for (int t = 0; t < d; ++t) if (row[t] == j) return;
        if (d >= kcap) return;
        row[d] = j;
        deg[i] = d + 1;
    }
};

// k nearest columns per row via nth_element on a copy of the row indices.
static void build_knn(Graph& g, const double* cost, int k) {
    int n = g.n;
    std::vector<int> idx(n);
    std::vector<double> vals(n);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) { idx[j] = j; vals[j] = row[j]; }
        std::nth_element(idx.begin(), idx.begin() + k, idx.end(),
                         [&](int a, int b) { return vals[a] < vals[b]; });
        int* out = g.cand.data() + (size_t)i * g.kcap;
        for (int t = 0; t < k; ++t) out[t] = idx[t];
        g.deg[i] = k;
    }
}

static int auction_on(const Graph& g, const double* cost, std::vector<double>& price,
                      std::vector<int>& owner, int* assignment, double eps_final, double eps_factor) {
    int n = g.n;
    std::fill(price.begin(), price.end(), 0.0);
    double cmax = 1e-6;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        const int* c = g.cand.data() + (size_t)i * g.kcap;
        for (int t = 0; t < g.deg[i]; ++t) if (row[c[t]] > cmax) cmax = row[c[t]];
    }
    double eps = cmax;
    std::vector<int> free_rows(n), next_free(n);
    int rounds = 0;
    while (true) {
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment, assignment + n, -1);
        int nf = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        while (nf > 0 && guard++ < n * 100) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                const double* row = cost + (size_t)i * n;
                const int* c = g.cand.data() + (size_t)i * g.kcap;
                int d = g.deg[i];
                int j1 = c[0];
                double v1 = -row[j1] - price[j1];
                double v2 = NEG;
                for (int t = 1; t < d; ++t) {
                    int j = c[t];
                    double v = -row[j] - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                if (d == 1) v2 = v1 - 1.0;
                double bid = price[j1] + (v1 - v2) + eps;
                int prev = owner[j1];
                if (prev >= 0) {
                    assignment[prev] = -1;
                    next_free[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
            if (nf) std::memcpy(free_rows.data(), next_free.data(), nf * sizeof(int));
            ++rounds;
        }
        if (nf > 0) return -rounds;
        if (eps <= eps_final) break;
    }
    return rounds;
}

// Full-matrix certificate. Adds every column within `margin` of the best reduced benefit,
// plus the best itself. Returns number of rows that were not already optimal.
static int certify_and_extend(Graph& g, const double* cost, const double* price,
                              const int* assignment, double margin) {
    int n = g.n;
    int bad_rows = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int jstar = assignment[i];
        double vstar = -row[jstar] - price[jstar];
        double best = vstar;
        int jbest = jstar;
        for (int j = 0; j < n; ++j) {
            double v = -row[j] - price[j];
            if (v > best) { best = v; jbest = j; }
        }
        if (best > vstar + 1e-9) {
            ++bad_rows;
            g.add(i, jbest);
            // also add columns nearly as good as best, so the refined auction can move
            double cutoff = best - margin;
            for (int j = 0; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v >= cutoff) g.add(i, j);
            }
        }
    }
    return bad_rows;
}

static int solve(int n, const double* cost, int* assignment, int k, double eps_final) {
    Graph g(n, std::min(n, k + 64));
    build_knn(g, cost, k);
    std::vector<double> price(n), owner(n, -1);
    int rc = auction_on(g, cost, price, owner, assignment, 1e-4, 0.25);
    if (rc < 0) return -1;
    int bad = certify_and_extend(g, cost, price.data(), assignment, 1e-3);
    if (bad == 0) {
        // coarse solution already uniquely optimal at 1e-4; refine prices not required
        // but uniqueness margin is 1e-9 in the check above only vs current assignment.
        // A 1e-4-optimal assignment can still be the wrong permutation if several
        // edges are within 1e-4. The check best > vstar + 1e-9 catches any better edge,
        // so if bad==0 the assignment is optimal (every other edge is weakly worse).
        return 0;
    }
    rc = auction_on(g, cost, price, owner, assignment, eps_final, 0.25);
    if (rc < 0) return -2;
    bad = certify_and_extend(g, cost, price.data(), assignment, 1e-6);
    if (bad == 0) return 0;
    rc = auction_on(g, cost, price, owner, assignment, eps_final, 0.25);
    if (rc < 0) return -3;
    bad = certify_and_extend(g, cost, price.data(), assignment, 1e-8);
    return bad == 0 ? 0 : -4;
}

