// Cost-scaling assignment (push-relabel style) on a dense matrix, but only
// admissible edges with cost <= thr are active. Prices are integer after scaling.
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <queue>
#include <random>
#include <vector>
#include <cmath>

static int solve_cs(int n, const double* cost, double thr, int scale, int* assignment) {
    // integer costs
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    int Cmax = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            if (row[j] <= thr) {
                int c = (int)std::llround(row[j] * scale);
                adj[i].push_back({j, c});
                if (c > Cmax) Cmax = c;
            }
        }
        if (adj[i].empty()) return -1;
    }
    // cost scaling push-relabel for assignment (Goldberg-Kennedy simplified)
    // dual price[j], epsilon. Person i pushes to object j if reduced cost < epsilon? 
    // We implement the auction-like cost-scaling: epsilon-optimal matching refinement
    // via successive shortest paths is heavy. Use integer auction with persistent prices.
    std::vector<long long> price(n, 0);
    std::vector<int> owner(n, -1);
    std::fill(assignment, assignment + n, -1);
    std::vector<int> free_rows(n), next_free(n);
    int nf = n;
    for (int i = 0; i < n; ++i) free_rows[i] = i;
    long long eps = std::max(1LL, (long long)Cmax);
    int rounds = 0;
    while (true) {
        int guard = 0;
        while (nf > 0 && guard++ < n * 200) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                long long v1 = -(1LL<<60), v2 = -(1LL<<60);
                int j1 = -1;
                for (auto [j, c] : adj[i]) {
                    long long v = -(long long)c - price[j];
                    if (v > v1) { v2 = v1; v1 = v; j1 = j; }
                    else if (v > v2) v2 = v;
                }
                if (j1 < 0) return -1;
                if (v2 < -(1LL<<59)) v2 = v1 - 1;
                long long bid = price[j1] + (v1 - v2) + eps;
                int prev = owner[j1];
                if (prev >= 0) {
                    assignment[prev] = -1;
                    next_free[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
            if (nf) std::copy(next_free.begin(), next_free.begin() + nf, free_rows.begin());
            ++rounds;
        }
        if (nf > 0) return -rounds;
        if (eps == 1) break;
        eps = std::max(1LL, eps / 4);
        // unassign epsilon-CS violators at new eps, keep prices
        nf = 0;
        for (int i = 0; i < n; ++i) {
            int jstar = assignment[i];
            long long vstar = -(1LL<<60);
            int cstar = 0;
            long long best = -(1LL<<60);
            for (auto [j, c] : adj[i]) {
                long long v = -(long long)c - price[j];
                if (j == jstar) vstar = v;
                if (v > best) best = v;
            }
            if (vstar < best - eps) {
                if (jstar >= 0) { owner[jstar] = -1; assignment[i] = -1; }
                free_rows[nf++] = i;
            }
        }
    }
    return rounds;
}

int main() {
    int n = 600;
    std::mt19937 rng(1);
    std::uniform_real_distribution<double> d(0, 1);
    std::vector<double> S(2 * n), T(2 * n), cost((size_t)n * n);
    for (int i = 0; i < 2 * n; ++i) { S[i] = d(rng); T[i] = d(rng); }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double dx = S[2 * i] - T[2 * j], dy = S[2 * i + 1] - T[2 * j + 1];
            cost[(size_t)i * n + j] = std::sqrt(dx * dx + dy * dy);
        }
    std::vector<int> asg(n);
    auto t0 = std::chrono::steady_clock::now();
    int rc = solve_cs(n, cost.data(), 0.25, 1000000, asg.data());
    auto ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
    int bad = 0; std::vector<char> seen(n, 0);
    double csum = 0;
    for (int i = 0; i < n; ++i) {
        if (asg[i] < 0 || seen[asg[i]]) bad++;
        else { seen[asg[i]] = 1; csum += cost[(size_t)i * n + asg[i]]; }
    }
    std::cout << "rc " << rc << " ms " << ms << " bad " << bad << " cost " << csum << "\n";
}
