#include <Python.h>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>

// Integer cost-scaling auction on a thresholded bipartite graph, followed by a
// full-matrix reduced-cost certificate. Edges that violate the certificate are
// inserted and the auction is repeated, so the returned assignment is optimal
// for the dense problem (and, on these generic costs, the unique optimum).

struct Graph {
    int n;
    std::vector<std::vector<int>> cols;     // candidate columns
    std::vector<std::vector<int>> icost;    // scaled integer costs
    explicit Graph(int n_) : n(n_), cols(n_), icost(n_) {}
};

static void build_threshold(Graph& g, const double* cost, double thr, int scale) {
    int n = g.n;
    for (int i = 0; i < n; ++i) {
        g.cols[i].clear();
        g.icost[i].clear();
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            if (row[j] <= thr) {
                g.cols[i].push_back(j);
                g.icost[i].push_back((int)std::llround(row[j] * scale));
            }
        }
    }
}

static void add_edge(Graph& g, int i, int j, int cij) {
    for (int t = 0; t < (int)g.cols[i].size(); ++t) if (g.cols[i][t] == j) return;
    g.cols[i].push_back(j);
    g.icost[i].push_back(cij);
}

// Persistent-price integer auction. Returns 0 on a perfect matching, -1 otherwise.
static int auction(const Graph& g, std::vector<long long>& price, std::vector<int>& owner,
                   int* assignment, long long eps_final) {
    int n = g.n;
    std::fill(price.begin(), price.end(), 0);
    std::fill(owner.begin(), owner.end(), -1);
    std::fill(assignment, assignment + n, -1);
    long long cmax = 1;
    for (int i = 0; i < n; ++i)
        for (int c : g.icost[i]) if (c > cmax) cmax = c;
    long long eps = cmax;
    std::vector<int> free_rows(n), next_free(n);
    int nf = n;
    for (int i = 0; i < n; ++i) free_rows[i] = i;
    const long long NEG = -(1LL << 62);
    int phases = 0;
    while (true) {
        int guard = 0;
        const int guard_max = n * 80;
        while (nf > 0 && guard++ < guard_max) {
            int new_nf = 0;
            for (int kf = 0; kf < nf; ++kf) {
                int i = free_rows[kf];
                const auto& cols = g.cols[i];
                const auto& ic = g.icost[i];
                int d = (int)cols.size();
                if (d == 0) return -1;
                long long v1 = NEG, v2 = NEG;
                int j1 = cols[0];
                for (int t = 0; t < d; ++t) {
                    long long v = -(long long)ic[t] - price[cols[t]];
                    if (v > v1) { v2 = v1; v1 = v; j1 = cols[t]; }
                    else if (v > v2) v2 = v;
                }
                if (d == 1) v2 = v1 - 1;
                long long bid = price[j1] + (v1 - v2) + eps;
                int prev = owner[j1];
                if (prev >= 0) {
                    assignment[prev] = -1;
                    next_free[new_nf++] = prev;
                }
                owner[j1] = i;
                assignment[i] = j1;
                price[j1] = bid;
            }
            nf = new_nf;
            if (nf) std::memcpy(free_rows.data(), next_free.data(), nf * sizeof(int));
        }
        if (nf > 0) return -1;
        if (eps <= eps_final) break;
        long long next = std::max(eps_final, eps / 4);
        // drop rows that violate epsilon-CS at the tighter epsilon; keep prices
        nf = 0;
        for (int i = 0; i < n; ++i) {
            int jstar = assignment[i];
            long long vstar = NEG, best = NEG;
            const auto& cols = g.cols[i];
            const auto& ic = g.icost[i];
            for (int t = 0; t < (int)cols.size(); ++t) {
                long long v = -(long long)ic[t] - price[cols[t]];
                if (cols[t] == jstar) vstar = v;
                if (v > best) best = v;
            }
            if (vstar < best - next) {
                owner[jstar] = -1;
                assignment[i] = -1;
                free_rows[nf++] = i;
            }
        }
        eps = next;
        if (++phases > 40) break;
    }
    return 0;
}

// Add columns whose true reduced cost beats the assigned edge. Returns how many rows changed.
static int extend_from_full(Graph& g, const double* cost, int scale,
                            const std::vector<long long>& price, const int* assignment) {
    int n = g.n;
    int added_rows = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int jstar = assignment[i];
        long long vstar = -(long long)std::llround(row[jstar] * scale) - price[jstar];
        long long best = vstar;
        int jbest = jstar;
        for (int j = 0; j < n; ++j) {
            long long v = -(long long)std::llround(row[j] * scale) - price[j];
            if (v > best) { best = v; jbest = j; }
        }
        if (jbest != jstar) {
            add_edge(g, i, jbest, (int)std::llround(row[jbest] * scale));
            ++added_rows;
        }
    }
    return added_rows;
}

static int solve(int n, const double* cost, int* assignment, double thr, int scale) {
    Graph g(n);
    build_threshold(g, cost, thr, scale);
    std::vector<long long> price(n);
    std::vector<int> owner(n);
    for (int pass = 0; pass < 6; ++pass) {
        int rc = auction(g, price, owner, assignment, 1);
        if (rc != 0) {
            thr *= 1.5;
            if (thr > 1.5) return -1;
            g = Graph(n);
            build_threshold(g, cost, thr, scale);
            continue;
        }
        int added = extend_from_full(g, cost, scale, price, assignment);
        if (added == 0) return 0;
    }
    return -2;
}

static PyObject* py_solve(PyObject*, PyObject* args) {
    PyObject* obj;
    double thr = 0.22;
    int scale = 1000000;
    if (!PyArg_ParseTuple(args, "O|di", &obj, &thr, &scale)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_ND | PyBUF_STRIDES) != 0) return NULL;
    int n = (int)buf.shape[0];
    if (buf.ndim != 2 || buf.shape[1] != n || buf.itemsize != (Py_ssize_t)sizeof(double)
        || buf.strides[1] != (Py_ssize_t)sizeof(double)
        || buf.strides[0] != n * (Py_ssize_t)sizeof(double)) {
        PyBuffer_Release(&buf);
        PyErr_SetString(PyExc_ValueError, "need square C-contiguous float64");
        return NULL;
    }
    std::vector<int> asg(n, -1);
    int rc = solve(n, (const double*)buf.buf, asg.data(), thr, scale);
    PyBuffer_Release(&buf);
    if (rc != 0) {
        PyErr_Format(PyExc_RuntimeError, "solve failed %d", rc);
        return NULL;
    }
    PyObject* list = PyList_New(n);
    for (int i = 0; i < n; ++i) PyList_SET_ITEM(list, i, PyLong_FromLong(asg[i]));
    return list;
}

static PyMethodDef methods[] = {{"solve", py_solve, METH_VARARGS, ""}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "emd_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_emd_fast(void) { return PyModule_Create(&moduledef); }
